/// <summary>Registers this assembly's generated mediator with the scoped lifetime, and the real-world services.</summary>
public static class MediatorScopedFanOutSetup
{
    public static IServiceCollection AddMediatorScopedFanOutBenchmarks(this IServiceCollection services)
    {
        services.AddRealWorldServices();
        // The generator reads these options from this call at compile time.
        return services.AddMediator(
            static (MediatorOptions options) =>
            {
                options.Namespace = "Keryx.Benchmarks.FanOut.MediatorScoped";
                options.ServiceLifetime = ServiceLifetime.Scoped;
            }
        );
    }
}
